  Image *image = NULL;
  int status;

  assert(image_info != (ImageInfo *)NULL);
  assert(exception != (ExceptionInfo *)NULL);
  (void)ResetExceptionInfo(exception);

  image = AcquireImage(image_info, exception);
  if (image == (Image *)NULL)
    return (Image *)NULL;

  if (image->storage_class == PseudoClass) {
    if (AllocateImageColormap(image, 2, exception) != MagickTrue) {
      InheritException(exception, &image->exception);
      return (Image *)NULL;
    }
  }

  status = OpenBlob(image_info, image, ReadBlob, exception);
  if (status == MagickFalse) {
    ThrowFileException(exception, FileOpenError, UnableToOpenImage,
      image->filename);
    return (Image *)NULL;
  }

  if (image->columns == 0 || image->rows == 0) {
    CloseBlob(image);
    return (Image *)NULL;
  }

  if (image->ping) {
    CloseBlob(image);
    return image;
  }

  if (image->depth != 1) {
    (void)SetImageDepth(image, 1, exception);
  }

  (void)SetImageStorageClass(image, DirectClass, exception);
  (void)SetImageType(image, BilevelType, exception);

  for (ssize_t y = 0; y < (ssize_t)image->rows; y++) {
    unsigned char *scanline = (unsigned char *)AcquireMemory(image->columns);
    if (scanline == (unsigned char *)NULL) {
      ThrowMemoryException(exception);
      return (Image *)NULL;
    }

    for (ssize_t x = 0; x < (ssize_t)image->columns; x++) {
      unsigned char bit;
      if (ReadBlobByte(image) == EOF) {
        InheritException(exception, &image->exception);
        RelinquishMemory(scanline);
        return (Image *)NULL;
      }
      bit = (unsigned char)(GetBlobByte(image));
      if ((bit & 0x01) != 0)
        scanline[x] = 0;
      else
        scanline[x] = 255;
    }

    (void)ImportImagePixels(image, 0, y, image->columns, 1, "RGBO", CharPixel,
      scanline, exception);
    RelinquishMemory(scanline);
  }

  CloseBlob(image);
  return image;
}

Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image;
  ssize_t y;
  unsigned char *pixels;

  assert(image_info != (ImageInfo *) NULL);
  assert(image_info->signature == MagickSignature);

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL)
    return (Image *) NULL;

  if (image_info->ping)
  {
    CloseBlob(image);
    return (image->previous != (Image *) NULL ? GetFirstImageInList(image) : image);
  }

  for (y = 0; y < (ssize_t) image->rows; y++)
  {
    pixels = (unsigned char *) AcquireMemory(image->columns);
    if (pixels == (unsigned char *) NULL)
    {
      ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image_info->filename);
      return (Image *) NULL;
    }

    if (ReadBlob(image, image->columns, pixels) != image->columns)
    {
      pixels = (unsigned char *) RelinquishMemory(pixels);
      ThrowBinaryException(CorruptImageError, "UnexpectedEndOfFile", image_info->filename);
      return (Image *) NULL;
    }

    (void) SetImagePixels(image, 0, y, image->columns, 1, pixels);
    pixels = (unsigned char *) RelinquishMemory(pixels);
  }

  if (SyncImagePixels(image) != MagickTrue)
  {
    ThrowBinaryException(ResourceLimitError, "MemoryAllocationFailed", image_info->filename);
    return (Image *) NULL;
  }

  return image;
}

