Image *ReadARTImage(const ImageInfo *image_info, ExceptionInfo *exception) {
  Image *image = NULL;
  Blob *blob = NULL;

  assert(image_info != (const ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  blob = OpenBlob(image_info, ReadMode, exception);
  if (blob == (Blob *) NULL)
    return (Image *) NULL;

  image = CloneImageInfoToImage(image_info, exception);
  if (image == (Image *) NULL) {
    CloseBlob(blob);
    return (Image *) NULL;
  }

  if (image->ping) {
    CloseBlob(blob);
    return GetFirstImageInList(image);
  }

  if (ReadImageExtent(image, blob, exception) != MagickPass) {
    DestroyImageList(image);
    CloseBlob(blob);
    return (Image *) NULL;
  }

  if (image->storage_class == BilevelClass) {
    if (ReadBilevelImage(image, blob, exception) != MagickPass) {
      DestroyImageList(image);
      CloseBlob(blob);
      return (Image *) NULL;
    }
  }

  if (ReadPixelData(image, blob, exception) != MagickPass) {
    DestroyImageList(image);
    CloseBlob(blob);
    return (Image *) NULL;
  }

  CloseBlob(blob);
  if (CheckForEOF(image, exception) != MagickPass) {
    DestroyImageList(image);
    return (Image *) NULL;
  }

  return image;
}
